-- ================================ 20261029141213_fix_comment_on_post_overload.sql

-- 20261029141213 fix_comment_on_post_overload
--
-- RECONSTRUCTED 2026-10-30. The objects this migration removed no longer exist
-- in production, so this file is the guard rather than a recovered dump: it
-- drops every public.comment_on_post overload except the canonical
-- (bigint, text, bigint) signature from 20261029122045_post_comment_threads.
--
-- Why it mattered: adding p_parent_id created a second overload instead of
-- replacing the first, and PostgREST then rejected rpc/comment_on_post as
-- ambiguous ("Could not choose the best candidate function"). Dropping by
-- identity rather than by hand keeps this correct even if another overload is
-- added later.

do $$
declare
  fn record;
begin
  for fn in
    select p.oid, pg_get_function_identity_arguments(p.oid) as args
      from pg_proc p
      join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public'
       and p.proname = 'comment_on_post'
  loop
    if fn.args <> 'p_post_id bigint, p_body text, p_parent_id bigint' then
      execute format('drop function public.comment_on_post(%s)', fn.args);
      raise notice 'dropped stale overload comment_on_post(%)', fn.args;
    end if;
  end loop;
end $$;

-- ================================ 20261029162942_restore_media_upload_policy.sql

-- 20261029162942 restore_media_upload_policy
--
-- RECONSTRUCTED 2026-10-30 from the live production catalog (pg_policy on
-- storage.objects). Idempotent, safe to replay.
--
-- What this migration owns: the INSERT policy on the private `media` bucket.
-- It had been lost — most likely a hand-run `drop policy` while debugging an
-- upload failure was never replaced — so every upload started failing with a
-- bare 403 from Storage while reads kept working. This restores it and keeps
-- the read/delete/update policies in the same place so they cannot drift apart
-- again.
--
-- can_manage_media(name) is the whole authorisation: the object path is
-- `kind/<profile id>/…` and the caller may only write inside their own folder.

drop policy if exists media_insert_own on storage.objects;
create policy media_insert_own on storage.objects
  for insert to authenticated
  with check (bucket_id = 'media' and can_manage_media(name));

-- Re-assert the companions; create policy has no "if not exists" form, hence
-- the drops. These are the same definitions as 20261013000026_media_security.
drop policy if exists media_private_read on storage.objects;
create policy media_private_read on storage.objects
  for select to authenticated
  using (bucket_id = 'media' and (can_view_media(name) ->> 'allowed')::boolean);

drop policy if exists media_update_own on storage.objects;
create policy media_update_own on storage.objects
  for update to authenticated
  using (bucket_id = 'media' and can_manage_media(name))
  with check (bucket_id = 'media' and can_manage_media(name));

drop policy if exists media_delete_own on storage.objects;
create policy media_delete_own on storage.objects
  for delete to authenticated
  using (bucket_id = 'media' and can_manage_media(name));

-- ================================ 20261029195516_video_container_support.sql

-- 20261029195516 video_container_support
--
-- RECONSTRUCTED 2026-10-30 from the live production catalog (pg_get_functiondef).
-- Idempotent (create or replace), safe to replay.
--
-- What this migration owns: the single table of "which container may this kind
-- of upload be", plus the content-type → extension map that feeds it.
--   * media_extension(content_type) -> extension | null
--   * media_kind_allows(kind, ext)  -> boolean
--
-- Before this, the checks lived inline in the upload paths and had drifted:
-- QuickTime and WebM clips were rejected by posts but accepted by messages, so
-- the same phone produced "that takes a photo or a short clip" on one screen
-- and uploaded fine on another. Both functions are IMMUTABLE, so the answer is
-- identical everywhere and cheap enough to call per row.

create or replace function public.media_extension(p_content_type text)
returns text
language sql
immutable
as $function$
  select case lower(split_part(coalesce(p_content_type, ''), ';', 1))
    when 'image/jpeg' then 'jpg'
    when 'image/png' then 'png'
    when 'image/webp' then 'webp'
    when 'image/heic' then 'heic'
    when 'audio/mpeg' then 'mp3'
    when 'audio/mp4' then 'm4a'
    when 'audio/aac' then 'm4a'
    when 'audio/x-m4a' then 'm4a'
    when 'video/mp4' then 'mp4'
    when 'video/webm' then 'webm'
    when 'video/quicktime' then 'mov'
    when 'video/x-m4v' then 'mp4'
    else null
  end
$function$;

create or replace function public.media_kind_allows(p_kind text, p_ext text)
returns boolean
language sql
immutable
as $function$
  select case
    when p_kind = 'photos' then p_ext in ('jpg', 'png', 'webp')
    when p_kind in ('moments', 'posts') then p_ext in ('jpg', 'png', 'webp', 'mp4', 'webm', 'mov')
    when p_kind in ('circles', 'messages') then p_ext in ('jpg', 'png', 'webp', 'm4a', 'mp3', 'mp4', 'webm', 'mov')
    when p_kind = 'vibes' then p_ext in ('mp4', 'webm', 'mov', 'jpg', 'png', 'webp')
    else false
  end
$function$;

-- Execution grants, matching production pg_proc.proacl.
revoke all on function public.media_extension(text) from public, anon, authenticated;
grant execute on function public.media_extension(text) to service_role;

notify pgrst, 'reload schema';

-- ================================ 20261029205829_post_saves.sql

-- 20261029205829 post_saves
--
-- RECONSTRUCTED 2026-10-30 from the live production catalog (columns,
-- pg_constraint, pg_indexes, pg_policy, pg_get_functiondef). Idempotent.
--
-- What this migration owns: keeping a post.
--   * post_saves table + RLS (you can only see and touch your own saves)
--   * save_post(post_id, saved)  - the only write path
--   * post_saved(post_id)        - cheap boolean for a detail screen
--   * saved_posts(limit, after)  - the Keeps list, read through can_view_post so
--                                 a saved post that later narrows its audience
--                                 simply stops appearing
--   * post_engagement() gains `saved`
--
-- Note the asymmetry with likes: a save is private. There is no count, no
-- notification and no way to discover who saved a post — which is why every
-- policy here is `user_id = me_id()` and nothing references post_saves in a
-- serialized payload other than the caller's own row.

create table if not exists public.post_saves (
  user_id    bigint not null references public.profiles(id) on delete cascade,
  post_id    bigint not null references public.posts(id) on delete cascade,
  created_at bigint not null default public.now_ms(),
  primary key (user_id, post_id)
);

create index if not exists post_saves_user_idx
  on public.post_saves (user_id, created_at desc);

alter table public.post_saves enable row level security;

drop policy if exists post_saves_select_own on public.post_saves;
create policy post_saves_select_own on public.post_saves
  for select to authenticated
  using (user_id = public.me_id());

drop policy if exists post_saves_insert_own on public.post_saves;
create policy post_saves_insert_own on public.post_saves
  for insert to authenticated
  with check (user_id = public.me_id());

drop policy if exists post_saves_delete_own on public.post_saves;
create policy post_saves_delete_own on public.post_saves
  for delete to authenticated
  using (user_id = public.me_id());

create or replace function public.save_post(p_post_id bigint, p_saved boolean default true)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  me bigint := public.me_id();
  po public.posts;
begin
  if me is null then
    perform public.crushly_fail(401, 'unauthorized', 'Please sign in again.');
  end if;

  select * into po from posts p where p.id = p_post_id;
  if not found or not public.can_view_post(po, me) then
    perform public.crushly_fail(404, '', 'That post isn’t available.');
  end if;

  if coalesce(p_saved, true) then
    insert into post_saves (user_id, post_id) values (me, po.id)
    on conflict do nothing;
  else
    delete from post_saves s where s.user_id = me and s.post_id = po.id;
  end if;

  return jsonb_build_object(
    'saved', exists (select 1 from post_saves s where s.user_id = me and s.post_id = po.id)
  );
end $function$;

create or replace function public.post_saved(p_post_id bigint)
returns boolean
language sql
stable security definer
set search_path to 'public'
as $function$
  select exists (
    select 1 from post_saves s
     where s.user_id = public.me_id()
       and s.post_id = p_post_id
  );
$function$;

create or replace function public.saved_posts(p_limit integer default 20, p_after bigint default null::bigint)
returns jsonb
language plpgsql
stable security definer
set search_path to 'public'
as $function$
declare
  me    bigint := public.me_id();
  items jsonb := '[]'::jsonb;
  r     record;
  post  public.posts;
begin
  if me is null then
    perform public.crushly_fail(401, 'unauthorized', 'Please sign in again.');
  end if;

  -- Cursor is the save's own timestamp, not the post's: you want the things you
  -- kept most recently, whatever order they were posted in.
  for r in
    select po.* from post_saves s
      join posts po on po.id = s.post_id
     where s.user_id = me
       and (p_after is null
            or s.created_at < (select s2.created_at from post_saves s2
                                where s2.user_id = me and s2.post_id = p_after)
            or (s.created_at = (select s2.created_at from post_saves s2
                                 where s2.user_id = me and s2.post_id = p_after)
                and po.id < p_after))
     order by s.created_at desc, po.id desc
     limit least(greatest(coalesce(p_limit, 20), 1), 50)
  loop
    select * into post from posts where id = r.id;
    if found and public.can_view_post(post, me) then
      items := items || jsonb_build_array(
        jsonb_build_object(
          'id', r.id,
          'body', r.body,
          'mediaUrl', r.media_url,
          'mediaKind', case
            when r.media_url is null then null
            when r.media_url ~ '\.(mp4|webm|mov|m4v)(\?|$)' then 'video'
            else 'photo'
          end,
          'edit', r.edit,
          'audience', r.audience,
          'circleId', r.circle_id,
          'createdAt', r.created_at,
          'author', public.public_profile(me, r.author_id, false),
          'mine', r.author_id = me
        ) || public.post_engagement(r.id, me) || jsonb_build_object('saved', true)
      );
    end if;
  end loop;

  return jsonb_build_object('items', items);
end $function$;

create or replace function public.post_engagement(p_post_id bigint, p_viewer bigint)
returns jsonb
language sql
stable security definer
set search_path to 'public'
as $function$
  select jsonb_build_object(
    'likeCount', (select count(*) from post_reactions r where r.post_id = p_post_id),
    'commentCount', (select count(*) from post_comments c where c.post_id = p_post_id and not c.hidden and not public.is_blocked_pair(p_viewer, c.author_id)),
    'liked', exists (select 1 from post_reactions r where r.post_id = p_post_id and r.user_id = p_viewer),
    'saved', exists (select 1 from post_saves s where s.post_id = p_post_id and s.user_id = p_viewer)
  );
$function$;

